alertExcerpt.code:
param databaseAccountName string
param actionGroupId string

@description('429 responses per 15 minutes that fire the alert.')
param throttleThreshold int = 50

resource database 'Microsoft.DocumentDB/databaseAccounts@2025-10-15' existing = {
  name: databaseAccountName
}

resource throttling 'Microsoft.Insights/metricAlerts@2026-01-01' = {
  name: '${databaseAccountName}-throttling'
  location: 'global'
  properties: {
    description: 'Cosmos DB returned 429 TooManyRequests above the threshold in 15 minutes.'
    severity: 3
    enabled: true
    scopes: [database.id]
    evaluationFrequency: 'PT5M'
    windowSize: 'PT15M'
    autoMitigate: true
    criteria: {
      'odata.type': 'Microsoft.Azure.Monitor.SingleResourceMultipleMetricCriteria'
      allOf: [
        {
          criterionType: 'StaticThresholdCriterion'
          name: 'throttled'
          metricNamespace: 'Microsoft.DocumentDB/databaseAccounts'
          metricName: 'TotalRequests'
          dimensions: [{ name: 'StatusCode', operator: 'Include', values: ['429'] }]
          operator: 'GreaterThan'
          threshold: throttleThreshold
          timeAggregation: 'Count'
        }
      ]
    }
    actions: [{ actionGroupId: actionGroupId }]
  }
}
